--
-- Estructura de tabla para la tabla `necesidad_empresa`
--

CREATE TABLE `necesidad_empresa` (
  `idnecesidad_empresa` int(11) NOT NULL,
  `perfil_empresario_idperfil_empresario` int(11) NOT NULL,
  `createdAt` timestamp NULL DEFAULT current_timestamp(),
  `changedAt` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_empresa_has_tipo_necesidad`
--

CREATE TABLE `necesidad_empresa_has_tipo_necesidad` (
  `necesidad_empresa_idnecesidad_empresa` int(11) NOT NULL,
  `tipo_necesidad_idtipo_necesidad` int(11) NOT NULL COMMENT '¿Qué tipo de necesidad tiene la empresa?',
  `prioridad` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_empresa_has_tipo_solucion`
--

CREATE TABLE `necesidad_empresa_has_tipo_solucion` (
  `necesidad_empresa_idnecesidad_empresa` int(11) NOT NULL,
  `tipo_solucion_idtipo_solucion` int(11) NOT NULL COMMENT '¿Qué tipo de solución está buscando la empresa para resolver su necesidad?'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_talento`
--

CREATE TABLE `necesidad_talento` (
  `idnecesidad_talento` int(11) NOT NULL,
  `necesidad_empresa_idnecesidad_empresa` int(11) NOT NULL,
  `tipo_talento_idtipo_talento` int(11) NOT NULL COMMENT '¿Qué tipo de talento es el que requiere?',
  `experiencia_talento_idexperiencia_talento` int(11) NOT NULL COMMENT '¿Qué tipo de experiencia requiere que tenga el talento que busca?',
  `subdisciplina_idsubdisciplina` int(11) NOT NULL COMMENT '¿En qué área del conocimiento requiere que se haya formado el talento que busca?',
  `rama_scian_idrama_scian` int(11) NOT NULL COMMENT '¿En qué industria necesita que su el talento tenga experiencia?',
  `cuando_obtener_talento_idcuando_obtener_talento` int(11) NOT NULL COMMENT '¿Para cuándo requiere obtener este talento?',
  `necesidad_talentocol` varchar(45) DEFAULT NULL,
  `createdAt` timestamp NULL DEFAULT current_timestamp(),
  `changedAt` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_talento_has_actividad_talento`
--

CREATE TABLE `necesidad_talento_has_actividad_talento` (
  `necesidad_talento_idnecesidad_talento` int(11) NOT NULL,
  `actividad_talento_idactividad_talento` int(11) NOT NULL COMMENT '¿Qué tipo de actividad requiere que desarrolle el talento que busca?'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_talento_has_habilidad_competencia`
--

CREATE TABLE `necesidad_talento_has_habilidad_competencia` (
  `necesidad_talento_idnecesidad_talento` int(11) NOT NULL,
  `habilidad_competencia_idhabilidad_compentencia` int(11) NOT NULL COMMENT '¿Qué tipo de habilidades y competencias necesito que tenga el talento que busco?'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `necesidad_tecnologia`
--

CREATE TABLE `necesidad_tecnologia` (
  `idnecesidad_tecnologia` int(11) NOT NULL COMMENT '¿Cuál sería una solución ideal a su necesidad con base en la tecnología?',
  `necesidad_empresa_idnecesidad_empresa` int(11) NOT NULL,
  `tipo_tecnologia_idtipo_tecnologia` int(11) NOT NULL,
  `verbo_solucion_idverbo_solucion` int(11) NOT NULL,
  `complemento` varchar(300) NOT NULL,
  `usuario_tecnologia_idusuario_tecnologia` int(11) NOT NULL,
  `como_obtener_solucion_idcomo_obtener_solucion` int(11) NOT NULL,
  `existe_solucion` tinyint(1) NOT NULL COMMENT '¿Cómo espera obtener esa solución?',
  `createdAt` timestamp NULL DEFAULT current_timestamp(),
  `changedAt` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- --------------------------------------------------------

