--
-- Estructura de tabla para la tabla `perfil_academico`
--

CREATE TABLE `perfil_academico` (
  `idperfil_academico` int(11) NOT NULL,
  `usuario_general_idusuario_general` int(11) NOT NULL,
  `grado_academico_idgrado_academico` int(11) NOT NULL COMMENT 'Último Grado académico obtenido',
  `titulo_obtenido` varchar(150) DEFAULT NULL COMMENT 'Título obtenido',
  `escuela` varchar(150) NOT NULL COMMENT 'Universidad o Centro de Investigación donde cursó sus estudios',
  `estudios_actuales` tinyint(1) NOT NULL COMMENT '¿Actualmente estoy estudiando?',
  `fecha_egreso` date DEFAULT NULL COMMENT '¿Mes y año de egreso?',
  `estimulo_beca_idestimulo_beca` int(11) NOT NULL COMMENT '¿Cuento con estímulos o becas?',
  `organizacion_actual` int(11) NOT NULL COMMENT 'Organización a la que pertenece actuamente',
  `funcion_academico_idfuncion_academico` int(11) DEFAULT NULL COMMENT 'Función en la actual organización',
  `subdisciplina_idsubdisciplina` int(11) NOT NULL COMMENT '¿En qué disciplina y subdisciplina has desarrollado tu experiencia?',
  `numero_tecnologias` int(11) DEFAULT 1,
  `createdAt` timestamp NULL DEFAULT current_timestamp(),
  `changedAt` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  `autorizo_publicar` tinyint(1) DEFAULT NULL COMMENT '¿Autorizo que mis datos sean públicos?'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

