--
-- Estructura de tabla para la tabla `tecnologia`
--

CREATE TABLE `tecnologia` (
  `idtecnologia` int(11) NOT NULL,
  `perfil_academico_idperfil_academico` int(11) DEFAULT NULL,
  `nombre` varchar(100) NOT NULL COMMENT 'Nombre de la tecnología',
  `tipo_alianza_idtipo_alianza` int(11) NOT NULL COMMENT '¿Qué tipo de alianza desear para explotar tu tecnología?',
  `autor_unico` tinyint(1) DEFAULT NULL COMMENT '¿soy el único autor de esta tecnología?',
  `autorizacion_propietario` varchar(1) DEFAULT NULL COMMENT '¿Soy propietario de la tecnología o tengo autorización de del propietario?',
  `autorizo_publicar` tinyint(1) DEFAULT NULL COMMENT '¿Autorizo que mis datos sean públicos?',
  `createdAt` timestamp NULL DEFAULT current_timestamp(),
  `changedAt` timestamp NULL DEFAULT NULL ON UPDATE current_timestamp(),
  `activo` tinyint(4) NOT NULL DEFAULT 1,
  `trl_anterior` int(11) DEFAULT 0,
  `usuario_general_idusuario_general` int(11) DEFAULT NULL
