--
-- Estructura de tabla para la tabla `trl_categoria`
--

CREATE TABLE `trl_categoria` (
  `idtrl_categoria` int(11) NOT NULL,
  `categoria` varchar(45) DEFAULT NULL,
  `descripcion` varchar(1000) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Volcado de datos para la tabla `trl_categoria`
--

INSERT INTO `trl_categoria` (`idtrl_categoria`, `categoria`, `descripcion`) VALUES
(1, 'General', 'Esta categoría incluye aspectos que describen la tecnología, sus principios, se prueba el concepto, los equipos necesarios, así como los procesos; y se evalúa si existe la documentación para la utilización y mantenimiento del producto final.'),
(2, 'Mercado', 'Los aspectos considerados en esta categoría se logran al conocer el problema o necesidad que aborda la tecnología, el mercado al que se pretende lanzar, el análisis de propuesta de valor y el modelo de negocios a aplicar.'),
(3, 'Desarrollo Temprano', 'Esta categoría comienza con aspectos relacionados a la investigación aplicada, considera la planeación del proyecto, la identificación de los componentes mínimos de la tecnología y el diseño preliminar de prototipos.'),
(4, 'Desarrollo Avanzado', 'Para obtener un resultado adecuado en esta sección se deben tener los prototipos a escala real o incluso el producto final para ser probado, el desarrollo debe estar caracterizado y documentado por completo, también se abordan estrategias de patentamiento. Al final se evalúa si ya se cuenta con un producto comerciable.'),
(5, 'Pruebas y Validación', 'Las pruebas del producto en todas las etapas (con base en la metodología TRL) se abordan en esta categoría. También se debe demostrar que la tecnología es viable completamente, y se abordan varios aspectos de nivel operativo.'),
(6, 'Manufactura y escalabilidad', 'Es la última categoría de la prueba, aborda aspectos puramente de producción: si la organización puede responder a la demanda del producto y si ha abordado el mantenimiento de la línea de producción o del producto en si (para algunos casos).');

