--
-- Estructura de tabla para la tabla `trl_glosario`
--

CREATE TABLE `trl_glosario` (
  `idtrl_glosario` int(11) NOT NULL,
  `concepto` varchar(45) DEFAULT NULL,
  `definicion` varchar(400) DEFAULT NULL,
  `trl_categoria_idtrl_categoria` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Volcado de datos para la tabla `trl_glosario`
--

INSERT INTO `trl_glosario` (`idtrl_glosario`, `concepto`, `definicion`, `trl_categoria_idtrl_categoria`) VALUES
(1, 'Ambiente real', 'Conjunto de condiciones reales en las que debe operar de forma sistemática la nueva tecnología o producto en la industria.', 1),
(2, 'Alcance de la tecnología', 'Describe las condiciones de operacion y aplicaciones de una tecnología, de acuerdo con los limites del proyecto y los recursos disponibles para su diseño y evaluación.', 3),
(3, 'Ambiente relevante', 'Conjunto de características en las que se puede probar un producto o prototipo, el cual es significativamente similar al entorno final en donde dicho producto se desempeñará.', 5),
(4, 'Barreras de entrada', 'Son obstáculos que por las caracteristicas del mercado o la empresa, dificultan el ingreso de nuevos productos o competidores.', 2),
(5, 'Caso de negocio', 'Plan o documento que responde a una oportunidad de negocio en el corto plazo; la estructura general de un caso se divide en 5 aspectos (estratégicos, tecnologicos, comerciales, financieros y administrativos).', 2),
(6, 'Casos de uso', 'Es el documento que registra las condiciones de operación técnica o comercial de un producto o tecnología determinada a través de una entidad de negocios.', 2),
(7, 'Dibujos preliminares de diseño', 'Formas específicas, materiales propuestos y planos con dimensiones generales, que representan al producto como un conjunto organizado de piezas, componentes, enlaces y acoplamientos.', 3),
(8, 'Diseño conceptual', 'Hipotesis documentada de un concepto o principio de solución de un problema o necesidad del mercado, con base en el conocimiento previo y demostrable en la literatura científica y tecnológica, materializada en un componente o prototipo susceptible de ser evaluado.', 4),
(9, 'Diseño detallado', 'Corresponde a la generación de todas las especificaciones necesarias para la producción del producto-solución. La elaboración de planos detallados, la determinación de etapas de fabricación y la identificación de proveedores son actividades de esta etapa.', 3),
(10, 'Documentación de capacitación', 'Todos aquellos documentos que permitan a los recursos humanos de una organización, entender y llevar a cabo los procesos de producción, administración y venta del producto o tecnología.', 1),
(11, 'Efectividad de la tecnología', 'Relación que existe entre los resultados logrados por el nuevo producto en comparación con los resultados que se esperaban del mismo.', 4),
(12, 'Entorno operativo', 'Conjunto de condiciones en las que será evaluada una tecnología o producto, que guardan relación cercana a las condiciones normales de operacin en una entidad de negocios.', 5),
(13, 'Entorno simulado o de simulación', 'Medio que permite probar de forma controlada las variables de desempeño de un nuevo producto, servicio o proceso, sin usar todos los recursos que implica su aplicación en el mundo real, pero obteniendo resultados muy parecidos.', 1),
(14, 'Escalabilidad de la tecnología', 'Capacidad de un nuevo producto de incrementar su alcance de aplicaciones, volumen de producción, logística y almacenamiento, compatibles con procesos de mejora para mantener su calidad.', 6),
(15, 'Estado del arte', '\"Documento que contiene el conocimiento disponible, documentado y actualizado sobre un tema específico en el campo de la ciencia y la tecnología, que responde a una pregunta de investigación con fines de validación de una hipótesis teórica o experimental.\n\"', 3),
(16, 'Estimaciones de costos preliminares', 'Análisis de información sobre las proyecciones o hipótesis de gastos e inversiones requeridos para el desarrollo de un proyecto o caso de negocio, que permitan generar presupuestos para estuidios de factibilidad financiera y económica.', 3),
(17, 'Estrategia de propiedad intelectual', 'Protocolos utilizados para administrar una cartera de activos de propiedad intelectual, con un énfasis en la obtención de títulos de propiedad, concesión de licencias y la presentación de recursos y estrategias legales ante eventuales litigios.', 4),
(18, 'Factibilidad de la tecnología', 'Se refiere a la disponibilidad y eficacia de los recursos necesarios para llevar a cabo el desarrollo de un proyecto, de nuevo producto y que este pueda introducirse en el mercado de manera favorable.', 3),
(19, 'Hipótesis de investigación', 'Son suposiciones o predicciones que se hacen sobre los resultados del trabajo de investigación. Se consideran guías que nos permiten orientar el trabajo a la obtención de un objetivo o conclusión determinada.', 3),
(20, 'Implementación operativa', 'Es la puesta en marcha del negocio, incluye los procesos de producción hasta los procesos de ventas de la nueva tecnología o producto.', 5),
(21, 'Infraestructura de investigación', 'Es el conjunto de todos aquellos elementos o dispositivos necesarios para la ejecución de las actividades y desarrollo de un determinado proyecto de investigación.', 3),
(22, 'Invención tecnológica', 'Resultado de un proceso creativo, generalmente con actividades de investigación, por medio de la cual surge una nueva solución a un problema social, en cualquier orden del conocimiento.', 3),
(23, 'Métricas de desempeño de la tecnológica', 'Indicadores cuantitativos obtenidos con la nueva tecnología o producto, que permiten evaluar el progreso logrado a través del desempeño esperado para solucionar el problema o reto técnico. ', 2),
(24, 'Modelo', 'Es una representación de la realidad de forma gráfica, mental o experimental, que facilita estudiar el comportamiento de un fenómeno y sus variables para una mejor comprensión del mismo.', 2),
(25, 'Organización operativa', 'Describe una empresa u organización que realiza cabalmente todas sus operaciones, es decir, cuenta con todos los procesos, estructura organizacional y recursos para su funcionamiento.', 2),
(26, 'Posicionamiento', 'Es la percepción de la asociación entre un producto o marca y sus atributos, en comparación con los productos que compiten directamente con él.', 2),
(27, 'Previsiones ambientales', 'Consideración que se deben tener al realizar el producto para que este no afecte el ambiente, en otras palabras, son las reglas ambientales que se dicten para el producto desarrollado.', 4),
(28, 'Previsiones legales', 'Consideración que se deben tener al realizar el producto para que este no infrinja con las leyes que lo rigen.', 4),
(29, 'Propiedad intelectual', 'Derecho que otorga el Estado a una persona sobre las creaciones de su mente: invenciones, obras literarias y artísticas, símbolos, nombres e imágenes utilizados en el comercio.', 3),
(30, 'Propuesta de valor', 'Enunciado que se estructura para integrar los factores que hace que un cliente se incline por uno u otro producto, para solucionar un problema o satisfacer una necesidad de manera innovadora.', 2),
(31, 'Prototipo funcional', 'Es un modelo del producto que es operativo en sentido estricto, el cual al activarse o ponerse en marcha responde a las entradas que le proporciona el usuario en tiempo real y efectúa alguna de las operaciones que se le solicitan.', 3),
(32, 'Prototipo escalable', 'Prototipo funcional al que fácilmente se le puede hacer mejoras o modificaciones con el fin de optimar su capacidad o calidad.', 4),
(33, 'Prueba de concepto', 'Modelo o prototipo experimental que permite poner a prueba un concepto o principio de solución de un problema o necesidad del mercado a través de un enfoque demostrativo.', 1),
(34, 'Riesgos financieros', 'Incertidumbre producida en el rendimiento de una inversión, debida a los cambios producidos en el sector en el que se opera, a la imposibilidad de devolución del capital y a la inestabilidad de los mercados financieros.', 3),
(35, 'Riesgos tecnológicos', 'Eventos relacionados con la implementación de nuevas tecnologías, que pueden tener impactos positivos o negativos en el proyecto y que pueden ocurrir con cierta probabilidad, así como derivar en problemas alternos.', 3),
(36, 'Riesgos de mercado', 'Posible pérdida de valor comercial o cuota de mercado de un producto o servicio en un plazo particular, provocado por cambios en las variables de mercado relacionadas con el uso, percepción y adopción del producto por los clientes.', 3),
(37, 'Simulación computacional', 'Ejecutar un programa informático en un entorno computacional, para saber cómo va a comportarse un sistema/tecnología que se busca representar o poner a prueba en determinadas condiciones.', 3),
(38, 'Simulación matemática', 'Consiste en la repetición de esquemas de cálculo basados en datos generados con números aleatorios. Los resultados obtenidos pueden aproximarse con apropiadas funciones de distribución de probabilidad.', 3),
(39, 'Usuario final', 'Se refiere a la persona o personas que van a manipular directamente el producto, el usuario final no es necesariamente sinónimo de cliente o comprador.', 2),
(40, 'Usuarios potenciales', 'Es toda aquella persona que en determinado momento puede convertirse en un comprador, usuario o consumidor de producto o servicio brindado.', 4),
(41, 'Verificación de tecnología', 'Es la acción de comprobar que el producto está realizando la función o funciones que establecimos al inicio del proyecto y casi siempre con la validación de cliente sobre el desempeño.', 5),
(42, 'Propuesta de valor completa', 'Se ha formulado el enunciado que describe de forma concreta y precisa, el valor que aporta la tecnología a cada segmento identificado de clientes, describiendo para ellos una combinación única de producto o servicio, su proceso de uso y beneficio medible esperado.', 2);

-- --------------------------------------------------------

