(5, 'Los grupos de clientes potenciales han sido identificados.', 2, 2, 3, NULL),
(6, 'Se cuenta con un grupo de investigación que pueda facilitar la evaluación inicial de factibilidad de la tecnología.', 2, 3, 1, NULL),
(7, 'Se han identificados los componentes de su invención tecnológica.', 2, 3, 3, NULL),
(8, 'Se cuenta con la infraestructura de investigación requerida.', 2, 3, 2, NULL),
(9, 'Se cuenta con la estrategia preliminar para obtener el prototipo funcional.', 2, 3, 2, NULL),
(10, 'Se tienen ya caracterizados los componentes individuales de la tecnología.', 2, 4, 3, NULL),
(11, 'Se ha hecho un análisis de la prueba de concepto como si estuviera funcionando en un entorno simulado.', 3, 1, 3, NULL),
(12, 'Se completó la evaluación de oportunidades de mercado (tamaño del mercado, competencia, barreras de entrada identificadas).', 3, 2, 4, NULL),
(13, 'La propuesta de valor inicial (concepto del caso de negocio) está completa.', 3, 2, 3, NULL),
(14, 'Se tiene certeza de que no se infringen derechos de propiedad intelectual.', 3, 3, 4, NULL),
(15, 'Ya se cuenta con una estrategia para identificar y proteger la propiedad intelectual.', 3, 3, 4, NULL),
(16, 'Se han creado prototipos funcionales de los componentes.', 3, 3, 3, NULL),
(17, 'Es posible generar modelos y simulaciones matemáticos y / o computacionales.', 3, 3, 2, NULL),
(18, 'El análisis del estado del arte muestra que la tecnología contribuye a satisfacer una necesidad del mercado.', 3, 3, 1, NULL),
(19, 'La invención tecnológica funciona a nivel laboratorio.', 3, 3, 4, NULL),
(20, 'Se ha definido como se escalará la producción de la tecnología o producto.', 3, 6, 4, NULL),
(21, 'Las pruebas a escala de laboratorio de los sistemas desarrollados se han completado en un entorno simulado.', 4, 1, 4, NULL),
(22, 'Los requisitos generales del sistema para la aplicación del usuario final son conocidos y documentados.', 4, 2, 5, NULL),
(23, 'Se han definido las métricas de desempeño de la tecnología.', 4, 2, 5, NULL),
(24, 'Se ha determinado si es necesaria una protección de patente a nivel nacional o internacional.', 4, 4, 5, NULL),
(25, 'Se han producido prototipos escalables (más grandes que a escala de laboratorio).', 4, 4, 5, NULL),
(26, 'Diseño conceptual desarrollado y documentado.', 4, 4, 3, NULL),
(27, 'Se han identificado los riesgos tecnológicos, de mercado y financieros, con un plan de mitigación de estos.', 4, 3, 4, NULL),
