(29, 'Se ha validado la efectividad de la tecnología en laboratorio.', 4, 4, 4, NULL),
(30, 'Se ha probado el prototipo en laboratorio con condiciones de un ambiente real.', 5, 1, 5, NULL),
(31, 'Se implementó una estrategia de propiedad intelectual.', 5, 4, 6, NULL),
(32, 'El prototipo a escala real cumple con las normas y o previsiones legales o ambientales del sector industrial donde se comercializará.', 5, 4, 6, NULL),
(33, 'Están preparadas las estimaciones de costos preliminares de productos comerciales.', 5, 3, 5, NULL),
