(36, 'Se cuenta con una organización operativa acorde a las necesidades (mercadotecnia, logística, producción y otros).', 6, 2, 7, NULL),
(37, 'La propuesta de valor se comprende por completo y se puede comunicar en menos de 1 minuto.', 6, 2, 6, NULL),
(38, 'Se cuenta con usuarios potenciales que prueben la versión final del producto.', 6, 4, 6, NULL),
