(41, 'Los prototipos han sido probados en un ambiente relevante bajo condiciones simuladas.', 6, 5, 5, NULL),
(42, 'Se han documentado las diferencias entre la escala de laboratorio y las pruebas en ambiente relevante.', 6, 5, 5, NULL),
