(48, 'El diseño final está en marcha y prácticamente completo.', 7, 4, 6, NULL),
(49, 'Se cuenta con un proceso de manufactura operacional en baja escala (produciendo productos comerciales).', 7, 6, 7, NULL),
(50, 'Se cuentan ya con los documentos para la utilización y mantenimiento del producto (manual del usuario, soporte técnico).', 8, 1, 8, NULL),
