(55, 'La viabilidad del desarrollo de la tecnología ha sido completamente demostrada.', 8, 5, 5, NULL),
(56, 'La empresa u organización que explotará la tecnología es operativa al 100 %.', 8, 5, 8, NULL),
(57, 'Los documentos para el uso y mantenimiento del producto (manual de usuario o soporte técnico), ya fueron revisados por las personas que se encargarán de esas tareas.', 8, 6, 8, NULL),
(58, 'Se está fabricando el producto en su versión final con niveles de producción aceptables.', 8, 6, 9, NULL),
