--
-- Estructura de tabla para la tabla `trl_recomendacion`
--

CREATE TABLE `trl_recomendacion` (
  `idrecomendacion` int(11) NOT NULL,
  `texto` varchar(300) DEFAULT NULL,
  `orden` int(11) DEFAULT NULL,
  `trl_nivel_idnivel` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

--
-- Volcado de datos para la tabla `trl_recomendacion`
--

INSERT INTO `trl_recomendacion` (`idrecomendacion`, `texto`, `orden`, `trl_nivel_idnivel`) VALUES
(1, 'Actualizar el estudio de mercado con indicadores específicos de los segmentos de interés ya validados. ', 4, 5),
(2, 'Actualizar el estudio del estado de la técnica contemplando la consulta de patentes y solicitudes de patente de los últimos 10 años. ', 1, 2),
(3, 'Actualizar el estudio del estado del arte contemplando la consulta de literatura científica de los últimos 5 años. ', 1, 1),
(4, 'Actualizar el plan de negocios contemplando las posibles alternativas de transferencia de tecnología. ', 7, 6),
(5, 'Actualizar estudios de costos, definir metas de cuotas de mercado y políticas de asignación de precios. ', 2, 9),
(6, 'Actualizar las proyecciones financieras del plan de negocios para la comercialización del producto, incluyendo indicadores de tasa de retorno, valor presente neto, punto de equilibrio y retorno de inversión. ', 5, 7),
(7, 'Actualizar los estudios del arte y de la técnica asegurando la obtención de datos de aplicaciones industriales de la tecnología. ', 6, 4),
(8, 'Actualizar modelo de negocios y elaborar el plan de negocios respectivo. ', 2, 5),
(9, 'Asegurar la búsqueda de patentes cuyo titular sean empresas líderes en la industria, o bien cuyos autores sean investigadores incorporados a universidades o centros de investigación. ', 4, 2),
(10, 'Consultar las aplicaciones comerciales de la tecnología con investigadores que se encuentren desarrollando proyectos de emprendimiento. ', 3, 4),
(11, 'Consultar literatura reportada en estudios de prospectiva tecnológica de fuentes oficiales o reconocidas por la industria haciendo enfasis en tecnologia emergentes. ', 3, 2),
(12, 'Consultar literatura reportada en estudios de prospectiva tecnológica de fuentes oficiales o reconocidas por la industrial. ', 5, 1),
(13, 'Consultar proyectos en incubadoras de alta tecnología o de negocios en instituciones de educación superior.', 5, 4),
(14, 'Consultar tendencias y criterios de inversión en programas de aceleración de negocios para el levantamiento de capital privado.', 6, 7),
(15, 'Diseñar el mapa de ruta comercial, que incluya los planes de escalabilidad y penetración de mercados, el cumplimiento de regulaciones internacionales y estudios de competitividad. ', 5, 8),
(16, 'Diseñar el modelo de negocios para cada segmento de clientes identificado con ayuda de las herramientas \"business model canvas\" , \"value proposition canvas\" y \"product/market fit canvas\". ', 6, 4),
(17, 'Diseñar la estrategia de protección de la propiedad intelectual contemplando la obtención de patentes, diseños industriales. modelos de utilidad, marcas y derechos de autor. ', 5, 5),
(18, 'Documentar el diseño definitivo del producto en un paquete tecnológico, incluyendo especificaciones del producto, tablas de diseño, ingeniería de detalle, ingeniería de empaque, cumplimiento regulatorio, manuales de usuario, manuales de capacitación y plan de contingencias. ', 3, 7),
(19, 'Documentar las condiciones y protocolos experimentales, incluyendo los retos tecnológicos enfrentados por cada componente.', 2, 5),
(20, 'Documentar las condiciones y protocolos experimentales, incluyendo los retos tecnológicos enfrentados por el sistema completo. ', 2, 6),
(21, 'Documentar los contenidos de mercadotecnia del producto, incluyendo perfiles de clientes y usuarios, atributos de la tecnología, criterios de adquisición de los clientes y procedimientos de venta y servicio al cliente. ', 4, 7),
(22, 'Documentar procedimientos de producción y control de calidad a gran escala, aseguramiento de especificaciones, planes de capacitación de los operarios, y de gestión de riesgos. ', 1, 9),
(23, 'Elaborar el mapa de ruta tecnológica que incluya los mercados meta y el tiempo de introducción del nuevo producto o servicio, así como los requerimientos del escalamiento productivo. ', 5, 6),
(24, 'Elaborar el perfil de los tomadores de decisiones a nivel técnico, legal y financiero para una posible transferencia de tecnología. ', 4, 6),
(25, 'Elaborar estudios de costos y planes de negocio para su presentación con inversionistas y clubes de inversión.', 7, 8),
(26, 'Elaborar estudios de nuevos clientes y usuarios, así como la identificación de oportunidades de mejora del producto para su adopción en nuevos mercados. ', 5, 9),
(27, 'Elaborar estudios de prospectiva tecnológica y comercial para la identificación de nuevas oportunidades de innovación del producto, servicio, mercadotecnia y organizacional. ', 6, 9),
(28, 'Elaborar la estrategia de introducción a nuevos mercados, que incluya los planes de marketing, contenidos de publicidad, planes de comunicación y relaciones públicas. ', 3, 9),
(29, 'Elaborar las estrategias de adopción masiva del producto con base en modelos de ciclo de vida y difusión de la tecnología, segmentación de clientes y usuarios y evidencias del valor percibido por el mercado.', 6, 8),
(30, 'Elaborar los planes de madurez operativa, que aseguren la adopción de nuevos procesos y prácticas de mejora que acompañan la asimilación de la tecnología. ', 3, 8),
(31, 'Identificar el mercado de aplicaciones de la tecnología y a las empresas que lo conforman, asegurando datos como el tamaño del mercado, su valor en dinero, tasa de crecimiento anual e impactos sociales y ambientales. ', 2, 3),
(32, 'Identificar los diferentes segmentos de clientes potenciales, con datos específicos de tipo de usuarios, montos de ventas, proyecciones de crecimiento y perspectivas regulatorias en los mercados de interés. ', 3, 4),
(33, 'Incorporar la consulta de estudios realizados por empresas o en líneas de centros de investigación privados.', 2, 1),
(34, 'Incorporar los contenidos del paquete tecnológico al sistema de gestión de calidad de la empresa, y los contenidos de mercadotecnia al plan de marketing corporativo. ', 2, 8),
(35, 'Obtener permisos regulatorios para la comercialización del producto en mercados meta. ', 4, 9),
(36, 'Realizar estudios de experiencia y satisfacción de clientes y usuarios, documentando las condiciones y protocolos de prueba, condiciones de usabilidad, así como los retos enfrentado. ', 2, 7),
(37, 'Realizar estudios de validación del potencial de comercialización de la tecnología (Quicklook Technology Assessment), con base en las necesidades reales del mercado. ', 2, 4),
(38, 'Realizar pruebas de desempeño de la tecnología en ambientes de simulación o laboratorio, controlando las variables que pueden afectar su desempeño en un entorno real. ', 1, 5),
(39, 'Realizar pruebas de desempeño de la tecnología y manufactura en ambientes reales a pequeña escala, contemplando los requerimientos de ambientes reales a gran escala. ', 1, 6),
(40, 'Realizar pruebas de manufactura a escala real, en condiciones de operación reales de los clientes, incluyendo procesos productivos, de empaque y logística. ', 1, 7),
(41, 'Realizar pruebas de manufactura y empaque del producto, considerando las variables para el escalamiento productivo y comercial. ', 1, 8),
(42, 'Realizar un estudio comparativo tecnológico entre tecnologías similares a la que se pretende desarrollar.', 1, 3),
(43, 'Realizar un estudio de libertad de operación (freedom to operate) a través de la consulta de patentes de aplicaciones industriales de la tecnología a nivel nacional e internacional.', 4, 3),
(44, 'Solicitar la propiedad intelectual de acuerdo con la estrategia de protección diseñada previamente. ', 6, 6),
(45, 'Validación del interés comercial de la tecnología con clientes potenciales específicos a través del método \"customer discovery\" y \"jobs to be done\". ', 3, 5),
(46, 'Validar el interés de clientes potenciales sobre los resultados obtenidos en las pruebas de desempeño de la tecnología. ', 3, 6),
(47, 'Validar las aplicaciones hipotéticas con especialistas en la industria y la academia.', 3, 3),
(48, 'Validar los procedimientos de venta, servicio y atención al cliente. ', 4, 8);

